              const tags = diffs.map((d) => d.tag).join(", ");
              console.log(
                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
              );
            }

            // Hide loading spinner on first update (cached items from SQLite
            // or live items from network — whichever arrives first)
            if (!receivedInitialItems) {
              receivedInitialItems = true;
              setLoadingMessage(false);
            }
          },
        });

        // Paginate backwards until we have a full page or reach the start.
        // Each call may only yield a few new items (SDK deduplicates against
        // its local store), so we loop.
        const MAX_PAGINATE_ROUNDS = 10;
        (async () => {
          try {
            for (let i = 0; i < MAX_PAGINATE_ROUNDS; i++) {
              if (isDisposed) return;
              const reachedStart =
                await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
              if (ENABLE_TIMELINE_DEBUG) {
                console.log(
                  `[TimelineDebug][${roomId}] paginate round ${i + 1}, reachedStart=${reachedStart}, items=${timelineItemsRef.current.length}`,
                );
              }
              if (
                reachedStart ||
                timelineItemsRef.current.length >= TIMELINE_PAGE_SIZE
              ) {
                break;
              }
            }
          } catch (error) {
            // Offline or network error — user already sees cached messages
            console.warn("Failed to load initial messages:", error);
          } finally {
            if (!isDisposed) setLoadingMessage(false);
          }
        })();
      } catch (error) {
        console.error("Failed to initialize room timeline:", error);
        offlineToastHelper("Failed to load the messages. Please try again.");
        NavigationContainerRef.goBack();
        return null;
      }
    };

    initRoomTimeline();

    return () => {
      isDisposed = true;
      timelineListenerHandle?.cancel?.();
      timelineRef.current = null;
      timelineItemsRef.current = [];
      isPaginatingRef.current = false;
      setRefreshing(false);
    };
  }, [rebuildEventsFromTimelineItems, room, roomId]);

  useEffect(() => {
    markAsRead().catch(console.error);
    room?.isDirect().then(setIsDirect).catch(console.error);
  }, [room, markAsRead]);

  return {
    events,
    loadingMessage,
    refreshing,
    timelineRef,
    isPaginatingRef,
    updateTrigger,
    isDirect,
    loadMoreMessages,
    markAsRead,
  };
};
